create extension if not exists pgcrypto;
create type public.client_type as enum ('CLIENTE_DIRECTO','BROKER');
create type public.lead_status as enum ('NUEVO','CONTACTADO','INTERESADO','CALIFICADO','VISITA_AGENDADA','NEGOCIACION','SEPARACION','CLIENTE','CERRADO','NO_INTERESADO');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade, first_name text not null, last_name text not null, whatsapp text, purchase_timeframe text, client_type public.client_type default 'CLIENTE_DIRECTO', role text default 'CLIENTE', created_at timestamptz default now());
create table public.properties(id uuid primary key default gen_random_uuid(), code text unique not null, slug text unique not null, title text not null, operation text not null, property_type text not null, price numeric not null, currency text not null check(currency in ('DOP','USD')), province text, municipality text, sector text, project text, description text, bedrooms int default 0, bathrooms int default 0, parking int default 0, construction_m2 numeric, land_m2 numeric, furnished boolean default false, status text default 'DISPONIBLE', latitude numeric, longitude numeric, created_at timestamptz default now());
create table public.favorites(user_id uuid references public.profiles(id) on delete cascade, property_id uuid references public.properties(id) on delete cascade, created_at timestamptz default now(), primary key(user_id,property_id));
create table public.crm_notes(id uuid primary key default gen_random_uuid(), client_id uuid references public.profiles(id) on delete cascade, admin_id uuid references public.profiles(id), note text not null, created_at timestamptz default now());
create table public.leads(id uuid primary key default gen_random_uuid(), client_id uuid references public.profiles(id) on delete cascade, property_id uuid references public.properties(id), action text not null, status public.lead_status default 'NUEVO', advisor_id uuid references public.profiles(id), created_at timestamptz default now());
create table public.appointments(id uuid primary key default gen_random_uuid(), client_id uuid references public.profiles(id), property_id uuid references public.properties(id), scheduled_at timestamptz not null, comment text, status text default 'PENDIENTE', created_at timestamptz default now());
alter table public.profiles enable row level security; alter table public.properties enable row level security; alter table public.favorites enable row level security;
create policy "public properties" on public.properties for select using (true);
create policy "own profile" on public.profiles for select using (auth.uid()=id);
create policy "own favorites" on public.favorites for all using (auth.uid()=user_id) with check(auth.uid()=user_id);
